def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        if history[0][1] == 'D':
            return 'D'
        return 'C'
    if n == 2:
        if history[0][1] == 'D' and history[1][1] == 'D':
            return 'D'
        if history[1][1] == 'D':
            return 'D'
        return 'C'

    opp_actions = [h[1] for h in history]
    my_actions = [h[0] for h in history]
    opp_defections = 0
    for o in opp_actions:
        if o == 'D':
            opp_defections += 1
    last_opp = opp_actions[-1]
    last_my = my_actions[-1]

    if n == 3:
        if opp_defections >= 2:
            return 'D'
        return 'D'

    if n == 4:
        if opp_defections >= 3 or opp_defections * 2 > n:
            return 'D'
        return 'C'

    remaining = 100 - n

    retal = 0
    forg = 0
    for i in range(n - 1):
        if my_actions[i] == 'D':
            if opp_actions[i + 1] == 'D':
                retal += 1
            else:
                forg += 1

    strict = False
    if retal > 0:
        strict = True
    if opp_defections * 2 > n:
        strict = True

    if remaining <= 1:
        return 'D'

    if strict:
        if opp_defections * 2 > n:
            return 'D'
        if opp_actions[-1] == 'D' and opp_actions[-2] == 'D':
            return 'D'
        if last_opp == 'D' and opp_defections > n // 4:
            return 'D'
        return 'C'
    else:
        if last_opp == 'D':
            if last_my == 'D':
                return 'C'
            else:
                return 'D'
        if last_my == 'D':
            return 'C'
        if opp_defections == 0 and n > 10:
            if remaining <= 3:
                return 'D'
            return 'D' if rng.random() < 0.9 else 'C'
        if n % 3 == 0:
            return 'D'
        if remaining <= 3:
            return 'D'
        return 'C'
